import {COW,COW_PRICES} from './cow-config.js';import {cowEffectiveGrade} from './cow-storage.js';
/** Canonical optimistic quote binds the revision, time, fraction, version and every selected batch. @param {import('./engine.js').State} state @param {string[]} ids @param {string} [order] */
export function cowSaleQuote(state,ids,order=''){const g=state.cow;if(!g)return '';return JSON.stringify([state.revision,state.tick,g.milkRevenueRemainder,g.balanceVersion,order,[...ids].sort().map(id=>{const l=g.lots.find(l=>l.id===id);return l?[id,l.remainingVolumeMl,l.collectedTick,l.freshnessScore,cowEffectiveGrade(l),l.storage]:[id];})]);}
/** @param {import('./engine.js').State} state @param {string[]} ids @param {string} [order] */
export function cowSalePlan(state,ids,order=''){const g=state.cow;const fail=(/** @type {string} */reason)=>({reason,volumeMl:0,numerator:0,coins:0,remainder:g?.milkRevenueRemainder||0,takes:/** @type {Array<{id:string,volumeMl:number}>} */([]),bonus:0,orderId:''});if(!g?.visited)return fail('cowNotVisited');if(!ids.length||new Set(ids).size!==ids.length)return fail('cowChooseMilk');if(order)return fail('cowOrderLocked');let volumeMl=0,numerator=0;const takes=[];for(const id of ids){const lot=g.lots.find(l=>l.id===id);if(!lot)return fail('cowLotMissing');const grade=cowEffectiveGrade(lot);if(!grade)return fail('cowMilkRejected');volumeMl+=lot.remainingVolumeMl;numerator+=lot.remainingVolumeMl*COW_PRICES[grade];takes.push({id,volumeMl:lot.remainingVolumeMl});}const total=numerator+g.milkRevenueRemainder;if(!Number.isSafeInteger(total)||!Number.isSafeInteger(g.stats.milkValueNumerator+numerator))return fail('cowSaleLimit');return {reason:'',volumeMl,numerator,coins:Math.floor(total/1000),remainder:total%1000,takes,bonus:0,orderId:''};}
/** @param {import('./engine.js').State} state @param {import('./engine.js').Command} command @param {import('./engine.js').DomainEvent[]} events @param {import('./cow-runtime.js').CowTransaction} transact */
export function applyCowSale(state,command,events,transact){const ids=command.cowLots||[],order=command.cowOrder||'',plan=cowSalePlan(state,ids,order);if(plan.reason)return plan.reason;if(command.cowQuote!==cowSaleQuote(state,ids,order))return 'cowSaleChanged';const g=state.cow;if(!g)return 'cowNotVisited';const before=g.milkRevenueRemainder,id=g.nextSale++;for(const take of plan.takes){const lot=g.lots.find(l=>l.id===take.id);if(lot)lot.remainingVolumeMl-=take.volumeMl;}g.lots=g.lots.filter(l=>l.remainingVolumeMl>0);g.soldMilkMl+=plan.volumeMl;g.stats.saleCount++;g.stats.milkValueNumerator+=plan.numerator;g.milkRevenueRemainder=plan.remainder;transact(state,'cow_milk_sale',plan.coins,command.id+':cow.sale:'+id);g.receipts.push({id,tick:state.tick,volumeMl:plan.volumeMl,coins:plan.coins,remainderBefore:before,remainderAfter:plan.remainder,orderId:plan.orderId,bonus:plan.bonus});if(g.receipts.length>COW.historyMax)g.receipts.shift();events.push({type:'cowMilkSold',amount:plan.coins});return '';}
